Task: Identify the edge case in this function:
```python
def compute_average(nums: list[float]) -> float:
    return sum(nums) / len(nums)
```
Analysis: If `nums` is empty, `len(nums)` is 0, raising `ZeroDivisionError`. Fix: Add `if not nums: return 0.0` at the start.

class LockFreeTreiberStack:
    # Atomic Compare-And-Swap (CAS) with memory_order_release / memory_order_acquire semantics
    # Invariant: Head updates prevent lost updates without mutexes, while Hazard Pointers mitigate the ABA race condition
    def __init__(self):
        self.head = AtomicReference(None)
    def push(self, val):
        new_node = Node(val)
        while True:
            old_head = self.head.get()
            new_node.next = old_head
            if self.head.compare_and_set(old_head, new_node):
                return True
